&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Calibri&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Calibri&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proactive in obtaining engineering or management input to solve issues&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Calibri&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Calibri&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Motivated to schedule own workload&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Calibri&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335551671&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Calibri&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;0&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excellent written and verbal communication skills, work well within a multinational team and with multinational customers. Excellent cultural awareness is essential.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Desirable&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience developing&amp;nbsp;firmware or drivers for&amp;nbsp;GPUs.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Knowledge of CUDA or OpenCL &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working on upstreaming of kernel code / contributing to Linux kernel.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Exposure to integration with data centre / cloud service operations – for example integration with Kubernetes or open stack.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;In addition to a competitive salary, Graphcore offers annual leave policy, medical and dental health plans, a gym card, and employee pension (matched up to 4%). We review our benefits on a yearly basis to ensure we offer a valuable and rewarding benefits programme to our employees. We welcome people of different backgrounds and experiences; we’re committed to building an inclusive work environment that makes Graphcore a great home for everyone. We offer an equal opportunity process and understand that there are visible and invisible differences in all of us. We can provide a flexible approach to interview and encourage you to chat to us if you require any reasonable adjustments.&lt;/p&gt;

base10-brex:greenhouse:8339283002.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Why join us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Brex is the intelligent finance platform that enables companies to spend smarter and move faster in more than 200 markets. By combining global corporate cards and banking with intuitive spend management, bill pay, and travel software, Brex enables founders and finance teams to accelerate operations, gain real-time visibility, and control spend effortlessly. Brex’s AI-native automation and world-class service eliminate manual expense and accounting tasks for customers so they can focus on what matters most. Tens of thousands of the world&#39;s best companies run on Brex, including DoorDash, Coinbase, Robinhood, Zoom, Plaid, Reddit, and SeatGeek.&lt;/p&gt;
&lt;p&gt;Working at Brex allows you to push your limits, challenge the status quo, and collaborate with some of the brightest minds in the industry. We’re committed to building a diverse team and inclusive culture and believe your potential should only be limited by how big you can dream. We make this a reality by empowering you with the tools, resources, and support you need to grow your career.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Engineering at Brex&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Engineering at Brex is about building systems that scale with speed and intention. Our teams span Software, Data, Security, and IT, and operate with high autonomy and deep collaboration. We tackle hard technical problems, own our outcomes, and push for excellence at every level — from architecture to deployment. It’s an environment where engineering is a craft, and builders become leaders.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Security Operations Engineer at Brex, you will focus on preventing, detecting and responding to security threats across Brex&#39;s corporate and cloud environments. You will use existing systems and develop tools to improve our security capabilities. Our team is responsible for functions across corporate security, detection &amp;amp; response and infrastructure security domains; and we perform systems engineering and automation to support those functions.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Security Operations is part of our wider Trust &amp;amp; IT organization which means you will have the opportunity to work closely with Application Security, Corporate Engineering, GRC and IT and to improve security configurations, drive positive employee behaviors and generally work to prevent events from becoming incidents. You will also help build and maintain our team’s open source project &lt;a href=&quot;https://medium.com/brexeng/announcing-substation-188d049d979b&quot;&gt;Substation&lt;/a&gt; and have the opportunity to contribute to the &lt;a href=&quot;https://medium.com/brexeng&quot;&gt;Brex Tech Blog&lt;/a&gt;. You’ll be part of a team that actively contributes to the wider security community and has a commitment to mentorship and engineering excellence.&lt;/p&gt;
&lt;p&gt;We’re looking for individuals with a strong background and interest in detecting, responding to, and resolving security incidents and security challenges. You should be comfortable dealing with lots of moving pieces, changing priorities, and new technologies, while having a keen eye for detail. Most importantly, you should be enthusiastic about working with a variety of backgrounds, roles, and people across Brex. Building a world-class financial service requires world-class security.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Where you’ll work&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role will be based in our Seattle office. We are a hybrid environment that combines the energy and connections of being in the office with the benefits and flexibility of working from home. We currently require a minimum of three coordinated days in the office per week, Monday, Wednesday and Thursday. As a perk, we also have up to four weeks per year of fully remote work!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Work on a highly cross-functional team to prevent, detect and respond to security threats across Brex&#39;s corporate and cloud environments&lt;/li&gt;
&lt;li&gt;Perform security incident response, investigation, remediation, and documentation, participate in periodic threat hunting and security exercises&lt;/li&gt;
&lt;li&gt;Leading, scoping and building features, participate in designing, and maintaining tools and systems which support the team’s domains – corporate security, detection &amp;amp; response and infrastructure security&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Collaborating and partnering with engineering and operations teams to drive remediation of security issues, while balancing prioritization of those security issues within SLA and teams’ respective backlogs&lt;/li&gt;
&lt;li&gt;Caring about secure system design, valuing building things correctly, an understanding of a MVP approach and an empathetic mindset when working with others&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree in Computer Science, Engineering or related field OR equivalent training / fellowship OR 5+ years work experienceExperience working in a corporate security, detection &amp;amp; response or infrastructure security role with responsibilities for security alert triage and security incident response&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Familiarity with CI/CD systems and DevOps workflows (e.g. Buildkite, Flux, Git, Terraform) in cloud environments (e.g. AWS, Azure, GCP)&lt;/li&gt;
&lt;li&gt;Experience with deploying and maintaining some of the security services and tools owned by the team (e.g. - SIEM, data pipelines, SOAR, domain monitoring, endpoint tooling, email protection tooling, cloud security tools)&lt;/li&gt;
&lt;li&gt;While not primarily a development role, the team develops and maintains tools written in Go and Python, so experience with coding is required&lt;/li&gt;
&lt;li&gt;You thrive in a collaborative environment filled with a diverse group of people with different expertise and backgrounds. We currently have around 30 nationalities represented with more than ½ the company working in a country different from the one they grew up in.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus points&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proficiency with Go and other programming languages&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with securing distributed systems in AWS, cloud and Kubernetes environments&lt;/li&gt;
&lt;li&gt;Contributions to the wider technical community (open source, public research, mentorship, community organizing, blogging, presentations, etc)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The expected salary range for this role is $192,000 - $240,000. However, the starting base pay will depend on a number of factors including the candidate’s location, skills, experience, market demands, and internal pay parity. Depending on the position offered, equity and other forms of compensation may be provided as part of a total compensation package.&lt;/p&gt;
&lt;p&gt;Brex LLC is a wholly owned subsidiary of Capital One, N.A.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;Please be aware, job-seekers may be at risk of targeting by malicious actors looking for personal data. Brex recruiters will only reach out via LinkedIn or email with a&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;http://brex.com/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;http://brex.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;brex.com&lt;/a&gt;&amp;nbsp;domain. Any outreach claiming to be from Brex via other sources should be ignored.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

base10-brex:greenhouse:8519265002.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Why join us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Brex is the intelligent finance platform that enables companies to spend smarter and move faster in more than 200 markets. By combining global corporate cards and banking with intuitive spend management, bill pay, and travel software, Brex enables founders and finance teams to accelerate operations, gain real-time visibility, and control spend effortlessly. Brex’s AI-native automation and world-class service eliminate manual expense and accounting tasks for customers so they can focus on what matters most. Tens of thousands of the world&#39;s best companies run on Brex, including DoorDash, Coinbase, Robinhood, Zoom, Plaid, Reddit, and SeatGeek.&lt;/p&gt;
&lt;p&gt;Working at Brex allows you to push your limits, challenge the status quo, and collaborate with some of the brightest minds in the industry. We’re committed to building a diverse team and inclusive culture and believe your potential should only be limited by how big you can dream. We make this a reality by empowering you with the tools, resources, and support you need to grow your career.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Sales at Brex&lt;/strong&gt;&lt;br&gt;The GTM team is the driving factor behind revenue for Brex and every member of our team directly affects our bottom line. We focus on generating new opportunities, acquiring new customers, and building even stronger relationships with our current customers. Our winning culture recognizes big team wins and celebrates individual accomplishments. We ensure that top performers are recognized and have built a competitive environment to motivate and unify the team.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Relationship Manager for our Startups team, you play a pivotal role in the success and satisfaction of our existing Startup clients by providing the necessary resources, guidance and support. This role requires excellent communication and interpersonal skills, a deep knowledge of Brex products, an understanding of the startup ecosystem and a passion for helping entrepreneurs and finance leaders achieve their goals.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Where you&#39;ll work&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role will be based in our San Francisco or New York City office. We are a hybrid environment that combines the energy and connections of being in the office with the benefits and flexibility of working from home. We currently require a minimum of three coordinated days in the office per week: Monday, Wednesday and Thursday. As a perk, we also have up to four weeks per year of fully remote work!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Manage a portfolio of approximately 200 companies (Seed through Series B+), serving as the primary point of contact for founders, CFOs, and Chiefs of Staff.&lt;/li&gt;
&lt;li&gt;Maintain deep awareness of each client&#39;s financial health, funding status, and growth trajectory to identify and address opportunities proactively.&lt;/li&gt;
&lt;li&gt;Uphold operational excellence through rigorous Salesforce hygiene and proficiency in tools such as Vitally, Gong, Scratchpad, HEX, Looker and LogRocket.&lt;/li&gt;
&lt;li&gt;Drive Net Revenue Retention (NRR) through the proactive expansion of products, including credit card utilization, growing banking deposits, adoption of bill pay, invoicing and travel products.&lt;/li&gt;
&lt;li&gt;Lead deposit acquisition by capturing fresh capital during financing rounds through the strategic positioning of Brex&#39;s banking and treasury solutions.&lt;/li&gt;
&lt;li&gt;Execute competitive defense strategies to protect your book of business, cultivating relationships built on trust rather than simple cash incentives.&lt;/li&gt;
&lt;li&gt;Partner through strategic collaboration with cross-functional teams to deliver optimal solutions, products, and services to our clients.&lt;/li&gt;
&lt;li&gt;Prioritize field engagement by targeting in-person interactions with customers by having in-person meetings and touch points.&lt;/li&gt;
&lt;li&gt;Manage event curation by hosting at least one monthly client event, such as intimate dinners, workout sessions, or other curated experiences.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;4+ years of experience in relationship management, account management, sales, partnerships, or a similar role, preferably within the startup or finance ecosystem or saas or banking industry.&lt;/li&gt;
&lt;li&gt;Consistent record of exceeding quota and delivering top performance in competitive sales environments.&lt;/li&gt;
&lt;li&gt;Excellent communication and interpersonal skills, with the ability to build and maintain relationships with diverse stakeholders.&lt;/li&gt;
&lt;li&gt;Proactive and results-oriented mindset, with the ability to work independently and as a part of a team.&lt;/li&gt;
&lt;li&gt;Strong organizational and project management skills, with the ability to multitask and prioritize effectively.&lt;/li&gt;
&lt;li&gt;Ability to analyze data and metrics to drive informed decisions and strategies.&lt;/li&gt;
&lt;li&gt;Strong understanding of the startup ecosystem.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The expected OTE range for this role is $181,000 - $226,000. The starting wage will depend on a number of factors including the candidate’s location, skills, experience, market demands, and internal pay parity. The OTE figure listed here includes base salary and commissions, which may or may not be earned depending on performance.&amp;nbsp; Depending on the position offered, equity and other forms of compensation may be provided as part of a total compensation package.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;Please be aware, job-seekers may be at risk of targeting by malicious actors looking for personal data. Brex recruiters will only reach out via LinkedIn or email with a&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;http://brex.com/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;http://brex.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;brex.com&lt;/a&gt;&amp;nbsp;domain. Any outreach claiming to be from Brex via other sources should be ignored.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

battery-bitwarden:greenhouse:7770756003.descriptionHtml:
&lt;p&gt;Bitwarden is the trusted identity security leader for millions of users worldwide, empowering enterprises, developers, and individuals to securely manage and share sensitive information anywhere. Bitwarden makes it easy for all users to extend robust security across their devices with password management, secrets management, and passwordless and passkey innovations. The company is headquartered in Santa Barbara, California. Learn more at&amp;nbsp;&lt;a href=&quot;https://bitwarden.com/&quot;&gt;bitwarden.com&lt;/a&gt;. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;The Security and IT team at Bitwarden is very active; we work with all teams across the organization every single day. You&#39;ll have the opportunity to contribute to a variety of projects and planning, and will be responsible for managing new and existing security and IT related requests for the business. This role reports directly to the Head of Information Security.&lt;/p&gt;
&lt;p&gt;This is an all-remote team, and Eastern U.S. time zone is preferred. We do not offer visa sponsorship at this time.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;RESPONSIBILITIES&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Assist with Security and IT related Technical Service Desk tickets&lt;/li&gt;
&lt;li&gt;First touch point for user support (investigation/resolution, referral to TSD/Senior team member, etc)&lt;/li&gt;
&lt;li&gt;Assist with access control changes, onboarding automation SCIM, and user provisioning / deprovisioning.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strong&lt;/strong&gt; hands-on expertise with configuring and administering/ maintaining Atlassian cloud products (JIRA, Service Management, Confluence, etc).&lt;/li&gt;
&lt;li&gt;Security and IT administrative tasks related to auditing, access management, and licensing users across various departments.&lt;/li&gt;
&lt;li&gt;Responds to, and where appropriate, resolves or escalates security incidents and investigations.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Assist Security and IT and other divisions with ensuring the secure and ethical implementation and operation of AI systems and data within the organization.&lt;/li&gt;
&lt;li&gt;Investigates, monitors and reviews SOC and SIEM alerts and network traffic for unusual or suspicious activity or security events, and investigates these as a first level responder. Provides escalations to tier 2 and tier3 SOC team as needed to assist with investigation of security events.&lt;/li&gt;
&lt;li&gt;Assist with developing and maintaining documentation for security systems, services and procedures to support Bitwarden’s security, compliance needs and certification requirements such as ISO 27001, SOC2, HIPAA, and GDPR.&lt;/li&gt;
&lt;li&gt;Administer and maintain endpoint protection and overall security and data protection utilizing various technologies such as Endpoint Detection and Response (EDR), Mobile Device Management (MDM), Secure Access Service Edge (SASE), Data Loss Prevention (DLP), DarkOps and Brand protection service, and other security solutions.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Establish and document standardized processes for managing security and IT services and establish secure/hardened system configuration baselines.&amp;nbsp; Document related IT process and procedures.&lt;/li&gt;
&lt;li&gt;Assist with patching and updating and overall vulnerability management to keep all systems and endpoint devices secure and operational with minimal downtime.&amp;nbsp; This includes Endpoint/ Asset standardization and maintaining OS and system updates/ patches, leveraging policy enforcements that are managed via our MDM&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;WHAT YOU BRING TO BITWARDEN&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Ability to provide security and IT related coverage ahead of the US East Coast time zone. This expands the availability of our security and IT team&lt;/li&gt;
&lt;li&gt;A Security and IT generalist that has prior experience working in environments with diverse technologies and can dive deep on domain expertise.&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience managing equipment and software across a distributed, remote, and decentralized global workforce&lt;/li&gt;
&lt;li&gt;Ability to maintain discretion, handle sensitive information and maintain security best-practices&lt;/li&gt;
&lt;li&gt;Interested in solving security and IT challenges through technical awareness, assurance, and partnership&lt;/li&gt;
&lt;li&gt;Security technocrat at heart, staying current with trends and new technologies&lt;/li&gt;
&lt;li&gt;Familiarity with security standards and regulations relevant to AI and data privacy&lt;/li&gt;
&lt;li&gt;Collaborative and adaptable mindset&lt;/li&gt;
&lt;li&gt;Openness and authenticity combined with excellent communication skills&lt;/li&gt;
&lt;li&gt;Excitement and enthusiasm for open source and for better internet security&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Excellent problem-solving skills – you might not know all the answers but you know how to find and communicate the solutions&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;WHAT TO EXPECT IN THE INTERVIEW PROCESS&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Meeting with our Recruiting team&lt;/li&gt;
&lt;li&gt;Interview with our Head of Information Security&lt;/li&gt;
&lt;li&gt;Interview/s with team members&lt;/li&gt;
&lt;li&gt;Reference calls&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;A FEW REASONS TO WORK WITH US&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Our user community loves us and we love them. Come to work each day with a sense of purpose as we bring a more secure internet experience to everyone from our friends and family to the world’s largest organizations.&lt;/li&gt;
&lt;li&gt;Become an expert. You’ll get immersed in the prominent technology markets of security and open source software.&lt;/li&gt;
&lt;li&gt;We are dedicated to building a diverse and talented team. Work remotely with motivated and supportive team members across the world.&lt;/li&gt;
&lt;li&gt;Learn and grow. Take on new challenges with the support of your team, and join our #growth-club to continue personal and professional development.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;In the United States, the starting base compensation range for this role is $115,000 - $145,000. Actual compensation may vary based on level, relevant experience, and skill set as assessed in the interview process, as well as market data by location. See our careers page for a list of benefits. Please note that compensation outside the U.S. will differ based on the market.&lt;/em&gt;&lt;/p&gt;

battery-cleerly:greenhouse:6010409004.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About Cleerly&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We’re Cleerly – a healthcare company that’s revolutionizing how heart disease is diagnosed, treated, and tracked. We were founded in 2017 by one of the world’s leading cardiologists and are a growing team of world-class engineering, operations, medical affairs, marketing, and sales leaders. We raised $223M in Series C funding in 2022 which has enabled rapid growth and continued support of our mission. In December 2024 we received an additional $106M in a Series C extension funding. Most of our teams work remotely and have access to our offices in Denver, Colorado, New, York, New York, Dallas, Texas, and Lisbon, Portugal with some roles requiring you to be on-site in a location.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Cleerly has created a new standard of care for heart disease through value-based, AI-driven precision diagnostic solutions with the goal of helping prevent heart attacks. Our technology goes beyond traditional measures of heart disease by enabling comprehensive quantification and characterization of atherosclerosis, or plaque buildup, in each of the heart arteries. Cleerly’s solutions are supported by more than a decade of performing some of the world’s largest clinical trials to identify important findings beyond symptoms that increase a person’s risk of heart attacks.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;At Cleerly, we collaborate digitally and use a wide variety of systems. Our people use Google Workspace (GMail, Drive, Docs, Sheets, Slides), Slack, Confluence/Jira, and Zoom Video, prior experience in these areas is a plus. Role or department specific technology needs may vary and will be listed as requirements in the job description.&amp;nbsp;&lt;/p&gt;
&lt;div id=&quot;C08UL92QPH8-1758651909.410819-thread-list-Thread_1758652385.135439&quot; class=&quot;c-virtual_list__item&quot; data-qa=&quot;virtual-list-item&quot; data-item-key=&quot;1758652385.135439&quot;&gt;
&lt;div class=&quot;c-message_kit__background c-message_kit__background--hovered c-message_kit__message c-message_kit__thread_message&quot; data-qa=&quot;message_container&quot; data-qa-unprocessed=&quot;false&quot; data-qa-placeholder=&quot;false&quot;&gt;
&lt;div class=&quot;c-message_kit__hover c-message_kit__hover--hovered&quot; data-qa-hover=&quot;true&quot;&gt;
&lt;div class=&quot;c-message_kit__actions c-message_kit__actions--default&quot;&gt;
&lt;div class=&quot;c-message_kit__gutter&quot;&gt;
&lt;div class=&quot;c-message_kit__gutter__right&quot; data-qa=&quot;message_content&quot;&gt;
&lt;div class=&quot;c-message_kit__blocks c-message_kit__blocks--rich_text&quot;&gt;
&lt;div class=&quot;c-message__message_blocks c-message__message_blocks--rich_text&quot; data-qa=&quot;message-text&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer&quot; data-qa=&quot;block-kit-renderer&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer__block_wrapper p-block_kit_renderer__block_wrapper--first&quot;&gt;
&lt;div class=&quot;p-rich_text_block&quot;&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;While we are mostly a remote company, travel is required for some team meetings and cross function projects typically once per month or once per quarter, for some roles like sales or external facing roles travel could be up to 90% of the time.&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;em&gt;Cleerly is committed to providing safe and effective medical software that meets customer needs and our intended use. The adherence to all applicable regulatory and statutory requirements establishes a clear framework for setting measurable quality objectives. Our commitment to continually improving our products and processes proactively manages risks, ensuring ongoing compliance throughout the entire software lifecycle. &amp;nbsp;Understanding this role&#39;s relevance and importance is critical to achieving Cleerly&#39;s quality objectives.&lt;/em&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Opportunity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Manager is accountable for ensuring the department maintains impeccable quality and delivers on time, addressing all short-term, mid-term, and long-term requirements necessary to achieve this outcome.&lt;/p&gt;
&lt;p&gt;This position demands a substantial strategic focus, requiring the incumbent to anticipate future needs years in advance and to comprehend how short-term actions contribute to and affect that long-term vision. The Manager is responsible for defining and proposing the requisite resources, organizational structure, and expertise for the department to consistently deliver flawless performance across all three timeframes.&lt;/p&gt;
&lt;p&gt;Furthermore, the Manager collaborates closely with the other Core Lab departments, and Imaging Services departments, to ensure alignment and efficient internal and external processes. The manager also works closely with the Training Department, as an internal client, to guarantee that the team&#39;s needs are met promptly. It also plays a role in potential expansions, providing resources and support for those endeavours.&lt;/p&gt;
&lt;p&gt;The incumbent plays a vital role in leadership, evaluation, and team development. The manager concentrates on scalability and process efficiency, working together with the Planning &amp;amp; Support team to deliver. While maintaining a primarily tactical focus, the Director remains involved in operational oversight, adopting a hands-off but observant approach to facilitate problem-solving and swift action. The role also actively contributes to defining metrics, ensuring consistent adherence to training, process, and quality standards, and emphasizing faultless execution, right-first-time results, and unwavering integrity across all operations.&lt;/p&gt;
&lt;p&gt;Is a key participant in cross functional teams regarding projects that impact the scans lifecycle workflows.&lt;/p&gt;
&lt;p&gt;The Manager reports to the Director, Imaging Services.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Leads the Core Lab Imaging Services, US based, including people, execution, budget, and capacity.&lt;/li&gt;
&lt;li&gt;Partakes, supporting the Imaging Services director, on defining capacity and budgets.&lt;/li&gt;
&lt;li&gt;Oversee daily operational targets and fosters the gap analysis of deviations and resulting actions for improvement, promoting Continuous Improvement.&lt;/li&gt;
&lt;li&gt;Partakes with the Planning &amp;amp; Support team on supervision team schedules, adjustments and daily issues, ensuring compliance with the defined capacity.&lt;/li&gt;
&lt;li&gt;Lead, support, or participate in Continuous Improvement projects within the Imaging Services Team and at the Core Lab level. Propose projects.&lt;/li&gt;
&lt;li&gt;Ensure compliance with training, process, and quality standards, flawless execution, right-first-time results, and integrity.&lt;/li&gt;
&lt;li&gt;Approves all the operational workflows and fosters the development and efficient and scalable processes, in alignment with the parallel departments.&lt;/li&gt;
&lt;li&gt;Evaluates the effectiveness of the processes and workflows via KPIs, and promotes action from the team.&lt;/li&gt;
&lt;li&gt;Provides operational workflows expertise to the Imaging Services Department and is the final decision-maker on people and workflow matters.&lt;/li&gt;
&lt;li&gt;Provides support for escalated issues on the processes and workflows.&lt;/li&gt;
&lt;li&gt;Responsible for developing the long term strategy for US Imaging Services, in all vectors, propose for approval and continuous monitoring of new needs.&lt;/li&gt;
&lt;li&gt;Partakes on the Imaging Services OKRs definition.&lt;/li&gt;
&lt;li&gt;Collaborates with other departments, including Product, Data Science, MSL, Research, and People.&lt;/li&gt;
&lt;li&gt;Partakes in the approval of the career pathways for Core Lab Imaging Services.&lt;/li&gt;
&lt;li&gt;Is part of the Core Lab Standardization team.&lt;/li&gt;
&lt;li&gt;Acts as a thought partner to the Director for scalability, efficiency and workflows.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;University degree in applicable field, technical, management or business. Technical knowledge of medical imaging (Preferred).&lt;/li&gt;
&lt;li&gt;Operational &amp;amp; Supply Chain Governance: Extensive experience navigating complex operations in supply chain management and/or fast paced operations management and/or process optimization considered as a plus&lt;/li&gt;
&lt;li&gt;Flexibility and agility: Experience managing within fast-paced, high-volatility operational environments, demonstrating the agility required to maintain performance stability under fluid conditions.&lt;/li&gt;
&lt;li&gt;Experience working in the healthcare context is a differentiator, as is knowledge of the regulated context of the SaMD.&lt;/li&gt;
&lt;li&gt;Technical knowledge of CCTA workflows: scan acquisition protocols and/or advanced post-processing is a plus&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Soft Skills&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strategic &amp;amp; People Leadership: Proven capability to drive organizational performance through team development, fostering a high-execution culture aligned with target KPIs..&lt;/li&gt;
&lt;li&gt;Cross-Functional Communication: Excellence in structured communication, possessing the articulation required to align multi-disciplinary teams and manage diverse stakeholder expectations.&lt;/li&gt;
&lt;li&gt;Tactical Project Execution: Advanced organizational and planning proficiency, focused on the rigorous execution of strategic projects and the mitigation of execution risks.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The base salary range for this role varies by location and is aligned to market benchmarks.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Candidates located in &lt;strong&gt;higher-cost labor markets&lt;/strong&gt;, including California, Washington, New York, New Jersey, Connecticut, Massachusetts, and Washington, DC represent the middle to high end of the range, while candidates located in &lt;strong&gt;all other U.S. locations &lt;/strong&gt;represent the low to middle end of the range.&lt;/li&gt;
&lt;li&gt;Final compensation is determined based on location, experience, skills, and internal equity.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;This role is eligible for a&amp;nbsp;&lt;strong&gt;15&lt;/strong&gt;&lt;strong&gt;% target annual bonus&lt;/strong&gt;, resulting in the following &lt;strong&gt;base salary &lt;/strong&gt;and &lt;strong&gt;Total Target Compensation (TTC)&lt;/strong&gt; ranges:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Base Salary: &lt;/strong&gt;&lt;strong&gt;&lt;em&gt;$112,000 - $130,000&lt;/em&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;TTC: &lt;/strong&gt;&lt;strong&gt;&lt;em&gt;$128,800 - $149,500&lt;/em&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;*Total Target Compensation (TTC): Total Cash Compensation (including base pay, variable pay, commission, bonuses, etc.) Additionally, stock options, paid benefits, and employee perks are part of your total rewards.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Working at Cleerly takes HEART. Discover our Core Values:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;1133&quot;&gt;&lt;strong&gt;H: Humility&lt;/strong&gt;- be a servant leader&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;1133&quot;&gt;&lt;strong&gt;E: Excellence&lt;/strong&gt;- deliver world-changing results&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;1133&quot;&gt;&lt;strong&gt;A: Accountability&lt;/strong&gt;- do what you say; expect the same from others&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;1133&quot;&gt;&lt;strong&gt;R: Remarkable&lt;/strong&gt;- inspire &amp;amp; innovate with impact&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;1133&quot;&gt;&lt;strong&gt;T: Teamwork&lt;/strong&gt;- together we win&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Don’t meet 100 percent of the qualifications? Apply anyway and help us diversify our candidate pool and workforce. We value experience, whether gained formally or informally on the job or through other experiences. &lt;em&gt;Job duties, activities and responsibilities are subject to change by our company.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;OUR COMPANY IS AN EQUAL OPPORTUNITY EMPLOYER.&lt;/em&gt;&lt;/strong&gt;&lt;em&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; &amp;nbsp;We do not discriminate on the basis of race, color, national origin, ancestry, citizenship status, protected veteran status, religion, physical or mental disability, marital status, sex, sexual orientation, gender identity or expression, age, or any other basis protected by law, ordinance, or regulation.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;For more information see our Privacy Policy (&lt;a href=&quot;https://cleerlyhealth.com/privacy-policy)&quot;&gt;https://cleerlyhealth.com/privacy-policy)&lt;/a&gt;. All official emails will come from @cleerlyhealth.com email accounts.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;#Cleerly&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

battery-sambanova-systems:greenhouse:585.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;The era of pervasive AI has arrived. In this era, organizations will use generative AI to unlock hidden value in their data, accelerate processes, reduce costs, drive efficiency and innovation to fundamentally transform their businesses and operations at scale.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;SambaNova Suite™ is the first full-stack, generative AI platform, from chip to model, optimized for enterprise and government organizations. Powered by the intelligent SN40L chip, the SambaNova Suite is a fully integrated platform, delivered on-premises or in the cloud, combined with state-of-the-art open-source models that can be easily and securely fine-tuned using customer data for greater accuracy. Once adapted with customer data, customers retain model ownership in perpetuity, so they can turn generative AI into one of their most valuable assets.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;SambaNova Systems is redefining what’s possible in AI infrastructure—and the hardware that powers it has to be flawless. As a Senior Hardware Validation &amp;amp; SI Correlation Engineer, you will own the technical bridge between simulation and silicon, ensuring that every high-speed link, control bus, and power rail in our next-generation AI server systems performs without compromise.&lt;/p&gt;
&lt;p&gt;This is a high-impact, highly visible role that blends deep Signal Integrity (SI) expertise with rigorous system-level hardware validation. You will work at the frontier of AI compute—validating PCIe Gen5/6, DDR5, and 112G/224G Ethernet interfaces on systems pushing the limits of what data center hardware can do. If you thrive in a fast-paced lab environment, love digging into root cause, and want your work to directly accelerate the future of AI, this role is built for you.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;SI Modeling &amp;amp; Measurement Correlation&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Drive the correlation between pre- and post-layout SI simulations and physical lab measurements, closing the loop between theory and hardware reality.&lt;/li&gt;
&lt;li&gt;Quantify simulation-vs-measurement gaps for PCIe Gen5/6, DDR5, and 112G/224G Ethernet using S-parameters, TDR, and eye diagram analysis.&lt;/li&gt;
&lt;li&gt;Develop and refine EM models for PCB discontinuities, high-speed connectors, and vias using Ansys HFSS, Cadence Sigrity, or equivalent tools.&lt;/li&gt;
&lt;li&gt;Investigate discrepancies caused by manufacturing tolerances, material properties (Dk/Df), or de-embedding inaccuracies and drive them to resolution.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;System-Level Electrical Validation&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead validation of housekeeping and control buses—I2C, SPI, eSPI, UART, SMBus—ensuring protocol compliance and robust timing margins.&lt;/li&gt;
&lt;li&gt;Validate complex power-on/off sequences and correlate VR control loop simulations with physical transient response and ripple measurements.&lt;/li&gt;
&lt;li&gt;Ensure reliable operation of sideband signals, reset logic, and BMC hardware interfaces under intensive AI workloads.&lt;/li&gt;
&lt;li&gt;Work cross-functionally with SI, Power Integrity (PI), and Firmware teams to resolve system-hang and link-training failures rooted in electrical noise or power instability.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Test Methodology &amp;amp; Automation&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Author comprehensive Hardware Validation Plans (HVP) with full coverage of critical electrical test points.&lt;/li&gt;
&lt;li&gt;Build Python-based automation scripts to drive data collection from VNAs, BERTs, and oscilloscopes—accelerating validation throughput and repeatability.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Bring&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Required&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;B.S. or M.S. in Electrical Engineering (M.S. preferred).&lt;/li&gt;
&lt;li&gt;10+ years of experience in high-speed digital design or hardware validation within a data center, systems architecture, or server bring-up environment.&lt;/li&gt;
&lt;li&gt;Expert-level proficiency in SI/EM tools: Ansys HFSS/SIwave, Cadence Sigrity/Allegro, or Keysight ADS.&lt;/li&gt;
&lt;li&gt;Hands-on mastery of high-bandwidth real-time oscilloscopes, VNAs, and logic analyzers.&lt;/li&gt;
&lt;li&gt;Deep knowledge of high-speed protocol physical layers (PCIe, IEEE 802.3) and low-speed control buses (I2C, SPI).&lt;/li&gt;
&lt;li&gt;Strong fundamentals in digital circuit design, debug, and computer architecture.&lt;/li&gt;
&lt;li&gt;Familiarity with the unique power and thermal challenges of high-density AI clusters—including 48V power delivery and high di/dt transients.&lt;/li&gt;
&lt;li&gt;Programming fluency in Python or equivalent scripting languages (Perl, Shell).&lt;/li&gt;
&lt;li&gt;PCIE Gen5/6 and 100g Ethernet Expertise&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Preferred&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;M.S. or Ph.D. with emphasis in Electromagnetics, Computer Architecture, or Power Electronics.&lt;/li&gt;
&lt;li&gt;Hands-on experience validating GPU/TPU modules or AI-specific interconnects such as NVLink or CXL.&lt;/li&gt;
&lt;li&gt;Ability to build end-to-end automated test frameworks in Python or TCL, integrating lab equipment with Pandas/NumPy for rapid correlation.&lt;/li&gt;
&lt;li&gt;Transaction- and link-layer expertise in PCIe Gen5/6 and DDR5—not just physical layer knowledge.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Why SambaNova Systems&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;SambaNova is at the center of the AI infrastructure revolution. We build the world’s most advanced AI platforms—from chip to system to software—and we’re looking for engineers who want to work on problems that matter at a scale that few companies can offer. You’ll join a team of world-class hardware and systems engineers, with access to cutting-edge equipment, fast iteration cycles, and the direct satisfaction of seeing your work power real AI deployments.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;Base Salary Range:&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Base Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$210,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$280,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Submission Guidelines&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Please note that in order to be considered an applicant for any position at SambaNova Systems, you must submit an application form for each position for which you believe you are qualified.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;EEO Policy&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;SambaNova Systems is an Equal Opportunity/Affirmative Action Employer. All qualified applicants will receive consideration for employment without regard basis of age (40 and over), color, disability, gender identity, genetic information, marital status, military or veteran status, national origin/ancestry, race, religion, creed, sex (including pregnancy, childbirth, breastfeeding), sexual orientation, and any other applicable status protected by federal, state, or local laws.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Benefits Summary for US-Based, Full-Time Employment Positions&lt;/strong&gt;&lt;br&gt;SambaNova offers a competitive total rewards package, including the base salary, plus equity and benefits. We cover 95% premium coverage for employee medical insurance, and 77% premium coverage for dependents and offer a Health Savings Account (HSA) with employer contribution. We also offer Dental, Vision, Short/Long term Disability, Basic Life, Voluntary Life, and AD&amp;amp;D insurance plans in addition to Flexible Spending Account (FSA) options like Health Care, Limited Purpose, and Dependent Care. Our library of well-being benefits available to you and your dependents includes a full subscription to Headspace, Gympass+ membership with access to physical gyms, One Medical membership, counseling services with an Employee Assistance Program, and much more.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

biocom-alamar-biosciences:greenhouse:567.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;At Alamar, we are passionate about enabling our customers to make scientific discoveries that translate into clinical outcomes and benefit patients. Our team is growing quickly as we develop innovative approaches to measure critical protein biomarkers from liquid samples that can enable the earliest possible detection of disease. We believe the next frontier in biology is enabled by measuring proteins at higher sensitivity in highly multiplexed assays at the push of a button, which is something only Alamar can do. As we build our team, we seek collaborative, driven, intellectually curious people committed to solving complex challenges. Our culture rewards accountability and cross functional teamwork because we believe this enables the kind of breakthrough thinking that will accelerate our mission.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;As a Senior Mechanical Engineer, you will play a critical role in sustaining our current proteomics instrument platform while driving the development of next-generation systems. You will collaborate with cross-functional teams—including R&amp;amp;D scientists, system engineers, software developers, and manufacturing experts—to ensure reliability, optimize performance, and innovate robust solutions. This role demands hands-on expertise, creative problem-solving, and a passion for advancing biotech instrumentation in a fast-paced startup environment.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Sustaining Engineering: Own mechanical reliability improvement projects (life testing, FMEA updates, failure analysis).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Drive design changes via ECOs and partner with Manufacturing to validate fixes.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Next-Generation Development: Build and bring‑up alpha/beta prototypes; define verification methods (gage R&amp;amp;R, test fixtures, acceptance criteria) and analyze results to iterate designs.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Partner with Systems/Software/Vendor to integrate sensors/actuators; define interfaces, alignment/adjustment schemes, and calibration methods.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;CAD: Develop and maintain 3D CAD models and assemblies using SolidWorks. Release production drawings with full GD&amp;amp;T and critical‑to‑quality callouts.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Hands-On Execution: Perform assembly, testing, and debugging in lab settings using diagnostic tools and equipment to verify functionality. Develop and validate testing or manufacturing fixtures.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Documentation: own BOMs, CAD, and production drawings with full GD&amp;amp;T; ensure change of traceability, serviceability, backwards compatibility and smooth change management with CM.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Manufacturing Integration: Identify advanced materials, suppliers and processes (e.g., injection molding, CNC machining, sheet metal fabrication) to improve cost-efficiency and system robustness.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Education: Bachelor’s or Master’s degree in Mechanical Engineering, Mechatronics, or a related field.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience: 6+ years in mechanical engineering for biotech instrumentation, medical devices, or life sciences platforms (e.g., NGS sequencers, PCR analyzers, or protein detection systems), with expertise in both sustaining and developing complex electro-mechanical systems.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Technical Skills:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Expert in 3D CAD modeling (SolidWorks preferred)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience designing precision gantry systems (e.g., XY/XYZ): linear guides, belts/lead screws/ball screws, stepper/BLDC drives, kinematics and backlash management, alignment/calibration methods, tolerance analysis, and safety/interlocks.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Expertise in mechanisms, materials, GD&amp;amp;T, and tolerance analysis.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Proficiency in structured problem-solving, verification/validation (V&amp;amp;V), and risk management processes.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Soft Skills:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Excellent analytical, problem-solving, written, and verbal communication skills.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Ability to collaborate across disciplines and present technical concepts clearly to non-experts.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Proactive, adaptable, and thrive in a fast-paced startup environment with a strong sense of ownership.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Preferred Qualifications:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Demonstrated ownership from concept → V&amp;amp;V → transfer to manufacturing → sustaining for a complex instrument or subsystem.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Background in machined, sheet metal, and injection molded parts and their production tooling.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience with biotech-specific challenges, such as integrating consumables, liquid-handling, or thermal control in high-throughput instruments.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Knowledge of ISO 13485 and other regulatory standards for medical devices or diagnostics.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;The base salary range for this full-time position is $150,000 - $170,000 + bonus + equity + benefits. Our salary ranges are determined by work location, job-related skills, experience, and relevant education or training. The ranges displayed on each job posting reflect the minimum and maximum target for new hire salaries but are subject to change if the leveling of the role is adjusted. Your recruiter can share more about the specific salary range during the hiring process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

biocom-bluebird-bio:greenhouse:7713770.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;
&lt;div data-tid=&quot;messageBodyContainer&quot;&gt;
&lt;div data-tid=&quot;messageBodyContent&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;About Genetix Biotherapeutics&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Genetix Biotherapeutics every role has meaning, every team member is respected, and every day is a chance to make a difference. When you join Genetix, you&#39;re not just landing a new role, you become part of a company that&#39;s pursuing curative gene therapies to give patients and their families more days. We are doers, thinkers and collaborators who embrace and live by our values:&lt;/p&gt;
&lt;p&gt;Our innovation is rooted in the diversity of our teams and results are achieved through cooperation and the integration of multiple viewpoints. This is personal and we approach every challenge with radical care.&lt;/p&gt;&lt;/div&gt;&lt;h4&gt;Position Description&lt;/h4&gt;
&lt;p&gt;The Senior Director, Regulatory CMC is responsible for defining and executing global CMC regulatory strategy for approved and late-stage gene therapy products, with a strong emphasis on lifecycle management, change management, and sustained regulatory compliance. This role provides strategic regulatory leadership across Genetix programs, ensuring efficient implementation of post-approval manufacturing, analytical, and control changes while maintaining product supply and inspection readiness.&lt;/p&gt;
&lt;p&gt;The Senior Director serves as a key regulatory partner to Technical Operations, Quality, and Supply Chain, and acts as the primary CMC regulatory interface with global health authorities for post-approval activities, including supplements, variations, annual reports, and inspection support.&lt;/p&gt;
&lt;p&gt;&lt;strong data-olk-copy-source=&quot;MessageBody&quot;&gt;This is a full-time hybrid position (3 days a week) in our Somerville, Massachusetts office.&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;h4&gt;Specific Job Duties&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Provide strategic leadership for post-approval CMC lifecycle management activities for Genetix gene therapy products, including planning and execution of global supplements, variations, and annual regulatory filings&lt;/li&gt;
&lt;li&gt;Own and drive global CMC change management strategy, assessing manufacturing, analytical, raw material, facility, and control strategy changes and defining optimal and aggressie regulatory pathways for implementation&lt;/li&gt;
&lt;li&gt;Lead regulatory CMC activities supporting commercial manufacturing, supply continuity, and inspection readiness, including responses to health authority questions and commitments&lt;/li&gt;
&lt;li&gt;Serve as the primary regulatory CMC lead for post-approval health authority interactions, including Type C/Scientific Advice meetings, responses to information requests, and support of GMP inspections&lt;/li&gt;
&lt;li&gt;Partner closely with Pharmaceutical Sciences, Technical Operations, Quality, Supply Chain, and Program Teams to ensure alignment between regulatory strategy and operational execution&lt;/li&gt;
&lt;li&gt;Provide regulatory oversight and approval of post-approval CMC documentation, ensuring consistency with approved dossiers and global regulatory requirements&lt;/li&gt;
&lt;li&gt;Drive adherence to global CMC regulatory standards and guidance (FDA, EMA, ICH) applicable to commercial and post-approval gene therapy products&lt;/li&gt;
&lt;li&gt;Contribute to and lead regulatory intelligence efforts related to post-approval expectations, emerging guidance, and evolving inspection trends impacting gene therapy products&lt;/li&gt;
&lt;li&gt;Mentor and develop Regulatory CMC team members, building scalable post-approval regulatory capabilities to support Genetix portfolio growth&lt;/li&gt;
&lt;li&gt;Represent Regulatory CMC on cross-functional governance forums, providing clear, risk-based regulatory recommendations&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;Required Education, Experience, or Qualifications&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s or Master’s degree in life sciences (biochemistry, chemistry, biology, biochemical engineering, or related field); PhD preferred&lt;/li&gt;
&lt;li&gt;Minimum of 15 years of biopharmaceutical industry experience, with significant experience in post-approval CMC regulatory affairs for cell and gene therapies&lt;/li&gt;
&lt;li&gt;Demonstrated experience leading post-approval submissions, including supplements, variations, and annual reports, and supporting health authority GMP inspections&lt;/li&gt;
&lt;li&gt;Strong working knowledge of commercial manufacturing and lifecycle management for complex biologics and gene therapy products&lt;/li&gt;
&lt;li&gt;Excellent written and verbal communication skills with proven ability to translate complex technical issues into clear regulatory strategies&lt;/li&gt;
&lt;li&gt;Proven leadership skills, including strategic thinking, people development, cross-functional influence, and decision-making in a matrix environment&lt;/li&gt;
&lt;li&gt;Deep understanding of GMP, CMC regulatory requirements, and global regulatory frameworks (FDA, EMA, ICH)&lt;/li&gt;
&lt;li&gt;Highly organized, detail-oriented, and solution-focused, with the ability to manage multiple priorities and drive execution to completion&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Additional Information&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The pay transparency range provided below is based on what we believe is a reasonable estimate for the base salary pay range for this job at the time of posting. We may ultimately pay more or less than the posted range, and the range may be modified in the future. This role is eligible for an annual bonus and long-term incentive. Actual base salary pay will be based on several factors, including but not limited to experience, skills, relevant education/qualifications, external market, internal equity, and other job-related factors permitted by law.&lt;/p&gt;
&lt;p&gt;Genetix’s total rewards package also provides employees with a comprehensive and competitive benefits suite to support a variety of employee needs. These benefits include comprehensive health, life and disability insurance, employer-matched 401(k) plan, lifestyle spending account, flexible time-off + paid holidays and winter holiday period, tuition reimbursement &amp;amp; loan repayment assistance, paid parental leave, paid onsite parking, commuter subsidy, and much more.&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Pay Transparency&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$156,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$316,500 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Genetix is proud to be an equal opportunity employer, seeking to create a welcoming and diverse environment.&amp;nbsp; All applicants will receive consideration for employment without regard to race, color, religion, gender, gender identity or expression, sexual orientation, national origin, genetics, disability, age, veteran status or any other applicable legally protected characteristics.&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;

biocom-calico-life-sciences:greenhouse:8.descriptionHtml:
&lt;p&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Calico (Calico Life Sciences LLC) is an Alphabet-founded research and development company whose mission is to harness advanced technologies and model systems to increase our understanding of the biology that controls human aging. Calico will use that knowledge to devise interventions that enable people to lead longer and healthier lives. Calico’s highly innovative technology labs, its commitment to curiosity-driven discovery science and, with academic and industry partners, its vibrant drug-development pipeline, together create an inspiring and exciting place to catalyze and enable medical breakthroughs.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Calico Postdoctoral Fellowship Program&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are seeking ambitious early career scientists to join us in our mission to increase our understanding of the biology that controls human aging. This is a unique opportunity for individuals to distinguish themselves in aging research, deepen scientific training, and develop research independence.&lt;/p&gt;
&lt;p&gt;The Postdoctoral Fellowship is a fixed-term educational assignment (three years with a potential fourth year extension) with rolling start dates. Postdoctoral Fellows are fully integrated into Calico&#39;s labs and community.&lt;/p&gt;
&lt;p&gt;The program is designed to train individuals to become independent investigators in an academic or industry setting upon successful completion of the assignment. Fellows will receive regular feedback and guidance from their mentor(s) and participate in a formal annual review process to review project progress and individual performance and provide career coaching.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Lead Independent Research:&lt;/strong&gt; Focus on their own project(s), which should pursue new research directions with dedicated resources for innovative and potentially high-risk/high-reward research&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Contribute to Calico’s Core Mission:&lt;/strong&gt; Contribute to furthering an understanding of aging and age-related diseases&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Drive Scientific Progress:&lt;/strong&gt; Execute experiments meticulously, analyze data (including computational analysis if applicable) and troubleshoot procedures as needed&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Publish Work:&lt;/strong&gt; Generate work that is expected to be submitted for publication in a timely fashion upon completion of the assignment&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Collaborate and Communicate:&lt;/strong&gt; Actively collaborate across Calico&#39;s diverse teams and scientific community, including presenting progress and results to diverse audiences of computational scientists, lab scientists, and engineers&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Professional Development:&lt;/strong&gt; Engage with a community of other Postdoctoral Fellows and senior leadership through professional and career development opportunities, such as the annual Postdoc Summit, research-in-progress presentations, senior leader lunch sessions, and skill-building workshops&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Position Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The successful candidate will demonstrate characteristics valued across Calico&#39;s programs, including being a self-motivated team player, detail-oriented, extremely organized, and comfortable working on complex problems.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Education:&lt;/strong&gt; Must have recently completed a PhD degree in a relevant scientific or computational field&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Current PhD student applicants should be within 12 months of completing their PhD&lt;/li&gt;
&lt;li&gt;Applicants who have already graduated must have completed their PhD within the past 3 years and not have been employed as a postdoc at more than one other lab/company since graduation&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;&lt;strong&gt;Experience:&lt;/strong&gt; Must have made important contributions to science in their area, ideally demonstrated by having had a meaningful first author paper accepted for publication&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Technical Versatility (General):&lt;/strong&gt; While specific technical skills are project-dependent, proficiency in core scientific methodologies, analytical skills, and quantitative problem-solving is essential&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Communication:&lt;/strong&gt; Strong teamwork and communication skills are required&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt; Must be flexible and able to respond quickly to shifting priorities, demonstrating a &quot;can-do&quot; attitude&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Onsite Availability: &lt;/strong&gt;Must be willing to work onsite five days per week&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Application Requirements&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Postdoctoral Fellowship has four application components:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Research proposal (a 1-2 page creative and original research proposal on what you’d like to investigate in the Nile Lab during your fellowship - note that project goals may evolve during the training period)&lt;/li&gt;
&lt;li&gt;Updated CV with a full list of publications&lt;/li&gt;
&lt;li&gt;Cover letter&lt;/li&gt;
&lt;li&gt;List of 2-3 references that we may contact, including your PhD thesis advisor and any postdoctoral advisors (if applicable)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The estimated base salary for this role is $95,000.&amp;nbsp;More information on our postdoctoral fellowship program can be found&amp;nbsp;&lt;span style=&quot;text-decoration: underline; color: rgb(53, 152, 219);&quot;&gt;&lt;a style=&quot;color: rgb(53, 152, 219); text-decoration: underline;&quot; href=&quot;https://www.calicolabs.com/postdoctoral-fellowship&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.calicolabs.com/postdoctoral-fellowship&amp;amp;source=gmail&amp;amp;ust=1771459299809000&amp;amp;usg=AOvVaw1pDUYdwqZ7ji3QVdiX4eqG&quot;&gt;here&lt;/a&gt;&lt;/span&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Nile Lab&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Nile Lab investigates the fundamental mechanisms by which E3 ubiquitin ligases recognize, modify, and regulate substrates. We aim to understand the biochemical and biophysical principles governing ubiquitin/UBL signaling, how E3s achieve specificity, how their activity is modulated, and how these insights can inform systematic strategies to redirect E3-ligase activity through chemical biology.&lt;br&gt;&lt;br&gt;Our research emphasizes rigorous protein biochemistry, including protein purification, quantitative mechanistic studies, and the reconstitution of multi-component systems &lt;em&gt;in vitro&lt;/em&gt;, while connecting these insights back to cellular context. We use a wide range of approaches such as structural biology, chemical biology, directed-evolution/selection technologies, and advanced imaging or biophysical methods. We welcome proposals that address core questions in ubiquitin signaling through rigorous biochemical experimentation and creative approaches. Ideal candidates will be highly quantitative, intellectually fearless, and collaborative team players who thrive in a multidisciplinary environment.&lt;/p&gt;
&lt;p&gt;Publications from the group include:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Full &lt;span style=&quot;text-decoration: underline; color: rgb(53, 152, 219);&quot;&gt;&lt;a style=&quot;color: rgb(53, 152, 219); text-decoration: underline;&quot; href=&quot;https://scholar.google.com/citations?user=6NjgInYAAAAJ&amp;amp;hl=en&quot; target=&quot;_blank&quot;&gt;Google Scholar&lt;/a&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;John Wang &amp;amp; Hannah Baddock &lt;em&gt;et al&lt;/em&gt;., Structure of the p53 degradation complex from HPV16 (2024) &lt;span style=&quot;text-decoration: underline; color: rgb(53, 152, 219);&quot;&gt;&lt;a style=&quot;color: rgb(53, 152, 219); text-decoration: underline;&quot; href=&quot;https://www.nature.com/articles/s41467-024-45920-w&quot; target=&quot;_blank&quot;&gt;Nature Communications&lt;/a&gt;&lt;/span&gt;&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;/li&gt;
&lt;li&gt;Peiyuan Zhang &amp;amp; Xiyun Ye &lt;em&gt;et al&lt;/em&gt;., Reversibly reactive affinity selection mass spectrometry enables maturation of covalent peptides (2024) &lt;span style=&quot;text-decoration: underline; color: rgb(53, 152, 219);&quot;&gt;&lt;a style=&quot;color: rgb(53, 152, 219); text-decoration: underline;&quot; href=&quot;https://pubs.acs.org/doi/abs/10.1021/jacs.4c05571&quot; target=&quot;_blank&quot;&gt;JACS&lt;/a&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Xiyun Ye &amp;amp; Peiyuan Zhang &lt;em&gt;et al&lt;/em&gt;., Discovery of reactive peptide inhibitors of human papillomavirus oncoprotein E6. (2023) &lt;span style=&quot;text-decoration: underline; color: rgb(53, 152, 219);&quot;&gt;&lt;a style=&quot;color: rgb(53, 152, 219); text-decoration: underline;&quot; href=&quot;https://pubs.rsc.org/en/content/articlelanding/2023/sc/d3sc02782a&quot; target=&quot;_blank&quot;&gt;Chemical Sciences&lt;/a&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

